// FNV-1a 32-bit: small, fast and stable across processes
function hash32(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

class HashRing {
  private positions: number[] = [];            // sorted
  private owner = new Map<number, string>();   // position -> node id
  constructor(private replicas = 100) {}

  addNode(id: string): void {
    for (let i = 0; i < this.replicas; i++) {
      const pos = hash32(`${id}#${i}`);
      if (this.owner.has(pos)) continue;          // rare collision: skip
      this.owner.set(pos, id);
      this.positions.push(pos);
    }
    this.positions.sort((a, b) => a - b);
  }

  removeNode(id: string): void {
    this.positions = this.positions.filter((p) => {
      const keep = this.owner.get(p) !== id;
      if (!keep) this.owner.delete(p);
      return keep;
    });
  }

  getNode(key: string): string | null {
    if (this.positions.length === 0) return null;
    const h = hash32(key);
    let lo = 0, hi = this.positions.length;       // first position >= h
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.positions[mid] >= h) hi = mid;
      else lo = mid + 1;
    }
    const pos = this.positions[lo % this.positions.length]; // wrap around
    return this.owner.get(pos)!;
  }
}

