import bisect

def fnv1a(s: str) -> int:
    h = 0x811C9DC5
    for b in s.encode():
        h ^= b
        h = (h * 0x01000193) & 0xFFFFFFFF
    return h

class HashRing:
    def __init__(self, replicas=100):
        self.replicas = replicas
        self.positions = []   # sorted
        self.owner = {}       # position -> node id

    def add_node(self, node):
        for i in range(self.replicas):
            pos = fnv1a(f'{node}#{i}')
            if pos in self.owner:
                continue
            self.owner[pos] = node
            bisect.insort(self.positions, pos)

    def remove_node(self, node):
        keep = [p for p in self.positions if self.owner[p] != node]
        for p in set(self.positions) - set(keep):
            del self.owner[p]
        self.positions = keep

    def get_node(self, key):
        if not self.positions:
            return None
        i = bisect.bisect_left(self.positions, fnv1a(key))
        return self.owner[self.positions[i % len(self.positions)]]

class HashRing {
    private final TreeMap<Integer, String> ring = new TreeMap<>();
    private final int replicas;
    HashRing(int replicas) { this.replicas = replicas; }

    void addNode(String id) {
        for (int i = 0; i < replicas; i++) ring.put(hash(id + "#" + i), id);
    }
    void removeNode(String id) {
        for (int i = 0; i < replicas; i++) ring.remove(hash(id + "#" + i));
    }
    String getNode(String key) {
        if (ring.isEmpty()) return null;
        Map.Entry<Integer, String> e = ring.ceilingEntry(hash(key)); // first >= hash
        return (e != null ? e : ring.firstEntry()).getValue();        // wrap around
    }
    private int hash(String s) { return s.hashCode() * 0x9E3779B1; /* use murmur3 in production */ }
}

class HashRing {
    std::map<uint32_t, std::string> ring;
    int replicas;
    static uint32_t fnv1a(const std::string& s) {
        uint32_t h = 2166136261u;
        for (unsigned char c : s) { h ^= c; h *= 16777619u; }
        return h;
    }
public:
    explicit HashRing(int r = 100) : replicas(r) {}
    void addNode(const std::string& id) {
        for (int i = 0; i < replicas; i++) ring[fnv1a(id + "#" + std::to_string(i))] = id;
    }
    void removeNode(const std::string& id) {
        for (int i = 0; i < replicas; i++) ring.erase(fnv1a(id + "#" + std::to_string(i)));
    }
    std::string getNode(const std::string& key) const {
        if (ring.empty()) return "";
        auto it = ring.lower_bound(fnv1a(key));
        return (it == ring.end() ? ring.begin() : it)->second;
    }
};

interface Versioned<V> { value: V; version: number }

interface Replica<V> {
  put(key: string, v: Versioned<V>): boolean;     // false if the replica is down
  get(key: string): Versioned<V> | null | undefined; // undefined = no answer (down)
}

class MemoryReplica<V> implements Replica<V> {
  private data = new Map<string, Versioned<V>>();
  down = false;
  put(key: string, v: Versioned<V>): boolean {
    if (this.down) return false;
    const cur = this.data.get(key);
    if (!cur || v.version > cur.version) this.data.set(key, v); // higher version wins
    return true;
  }
  get(key: string) {
    if (this.down) return undefined;
    return this.data.get(key) ?? null;
  }
}

class Coordinator<V> {
  private counter = 0;
  constructor(private replicas: Replica<V>[], private W: number, private R: number) {}

  write(key: string, value: V): void {
    const v = { value, version: ++this.counter };
    const acks = this.replicas.filter((r) => r.put(key, v)).length;
    if (acks < this.W) throw new Error('write quorum not reached');
  }

  read(key: string): V | null {
    const answers = this.replicas
      .map((r) => ({ r, v: r.get(key) }))
      .filter((a) => a.v !== undefined) as Array<{ r: Replica<V>; v: Versioned<V> | null }>;
    if (answers.length < this.R) throw new Error('read quorum not reached');
    const newest = answers.reduce<Versioned<V> | null>((best, a) => (a.v && (!best || a.v.version > best.version) ? a.v : best), null);
    if (newest) for (const a of answers) if (!a.v || a.v.version < newest.version) a.r.put(key, newest); // read repair
    return newest ? newest.value : null;
  }
}

// N=3, W=2, R=2  =>  R + W > N, reads see the latest write
const nodes = [new MemoryReplica<string>(), new MemoryReplica<string>(), new MemoryReplica<string>()];
const store = new Coordinator(nodes, 2, 2);

class MemoryReplica:
    def __init__(self):
        self.data = {}
        self.down = False

    def put(self, key, value, version):
        if self.down:
            return False
        cur = self.data.get(key)
        if cur is None or version > cur[1]:   # higher version wins
            self.data[key] = (value, version)
        return True

    def get(self, key):
        if self.down:
            raise ConnectionError
        return self.data.get(key)             # None if missing

class Coordinator:
    def __init__(self, replicas, w, r):
        self.replicas, self.w, self.r, self.counter = replicas, w, r, 0

    def write(self, key, value):
        self.counter += 1
        acks = sum(rep.put(key, value, self.counter) for rep in self.replicas)
        if acks < self.w:
            raise RuntimeError('write quorum not reached')

    def read(self, key):
        answers = []
        for rep in self.replicas:
            try:
                answers.append((rep, rep.get(key)))
            except ConnectionError:
                pass
        if len(answers) < self.r:
            raise RuntimeError('read quorum not reached')
        newest = max((v for _, v in answers if v), key=lambda v: v[1], default=None)
        if newest:
            for rep, v in answers:            # read repair
                if v is None or v[1] < newest[1]:
                    rep.put(key, *newest)
        return newest[0] if newest else None

