type Handler<T> = (msg: T) => void | Promise<void>;

class Subscription<T> {
  private queue: T[] = [];
  private running = false;
  constructor(readonly id: number, private handler: Handler<T>, private maxRetries = 3, private onDead?: (m: T, e: unknown) => void) {}

  deliver(msg: T): void {
    this.queue.push(msg);          // publisher never waits on the handler
    void this.drain();
  }

  private async drain(): Promise<void> {
    if (this.running) return;       // single worker keeps per-subscriber order
    this.running = true;
    while (this.queue.length) {
      const msg = this.queue.shift()!;
      for (let attempt = 1; ; attempt++) {
        try { await this.handler(msg); break; }
        catch (err) {
          if (attempt >= this.maxRetries) { this.onDead?.(msg, err); break; } // dead-letter
          await new Promise((r) => setTimeout(r, 2 ** attempt * 10));          // backoff
        }
      }
    }
    this.running = false;
  }
}

class Broker<T = unknown> {
  private topics = new Map<string, Map<number, Subscription<T>>>();
  private nextId = 1;
  readonly deadLetters: Array<{ topic: string; msg: T }> = [];

  subscribe(topic: string, handler: Handler<T>): () => void {
    const subs = this.topics.get(topic) ?? new Map();
    this.topics.set(topic, subs);
    const id = this.nextId++;
    subs.set(id, new Subscription<T>(id, handler, 3, (msg) => this.deadLetters.push({ topic, msg })));
    return () => subs.delete(id);   // unsubscribe
  }

  publish(topic: string, msg: T): number {
    const subs = this.topics.get(topic);
    if (!subs) return 0;
    for (const s of [...subs.values()]) s.deliver(msg); // iterate a snapshot
    return subs.size;
  }
}

