import queue, threading

class Subscription:
    def __init__(self, handler, max_retries=3, on_dead=None):
        self.q = queue.Queue()
        self.handler, self.max_retries, self.on_dead = handler, max_retries, on_dead
        threading.Thread(target=self._run, daemon=True).start()  # one worker keeps order

    def deliver(self, msg):
        self.q.put(msg)                      # publisher never waits on the handler

    def _run(self):
        while True:
            msg = self.q.get()
            for attempt in range(1, self.max_retries + 1):
                try:
                    self.handler(msg)
                    break
                except Exception as e:
                    if attempt == self.max_retries and self.on_dead:
                        self.on_dead(msg, e)  # dead-letter

class Broker:
    def __init__(self):
        self._topics = {}
        self._lock = threading.Lock()
        self.dead_letters = []

    def subscribe(self, topic, handler):
        sub = Subscription(handler, on_dead=lambda m, e: self.dead_letters.append((topic, m)))
        with self._lock:
            self._topics.setdefault(topic, []).append(sub)
        return sub

    def publish(self, topic, msg):
        with self._lock:
            subs = list(self._topics.get(topic, []))   # snapshot
        for s in subs:
            s.deliver(msg)
        return len(subs)

class Subscription<T> {
    private final BlockingQueue<T> queue = new LinkedBlockingQueue<>();
    Subscription(Consumer<T> handler) {
        Thread worker = new Thread(() -> {
            try {
                while (true) {
                    T msg = queue.take();          // one worker per subscriber keeps order
                    try { handler.accept(msg); } catch (Exception e) { /* retry / dead-letter */ }
                }
            } catch (InterruptedException ignored) {}
        });
        worker.setDaemon(true);
        worker.start();
    }
    void deliver(T msg) { queue.offer(msg); }     // publisher never blocks on the handler
}

class Broker<T> {
    private final Map<String, List<Subscription<T>>> topics = new ConcurrentHashMap<>();
    void subscribe(String topic, Consumer<T> handler) {
        topics.computeIfAbsent(topic, k -> new CopyOnWriteArrayList<>()).add(new Subscription<>(handler));
    }
    void publish(String topic, T msg) {
        for (Subscription<T> s : topics.getOrDefault(topic, List.of())) s.deliver(msg);
    }
}
